mapper.select:

where r.del_flag = '0'
  and r.rule_type = 'COND'
  and r.rule_id = #{ruleId}

mapper.delete:
delete from monitor_rule_condition c
 using monitor_rule r
 where r.rule_id = c.rule_id
   and r.site_code = #{scope.siteCode}
   and c.rule_id = #{ruleId}

mapper.insert:
insert into monitor_rule_condition (rule_id, seq, field_code, scope, how, op, unit, threshold_low, threshold_high, min_sample)
select #{row.ruleId}, #{row.seq}, #{row.fieldCode}, cast(#{row.scope} as jsonb), #{row.how}, #{row.op},
       #{row.unit,jdbcType=VARCHAR}, #{row.thresholdLow,jdbcType=NUMERIC}, #{row.thresholdHigh,jdbcType=NUMERIC},
       #{row.minSample,jdbcType=NUMERIC}
  from monitor_rule r
 where r.rule_id = #{row.ruleId}
   and r.site_code = #{scope.siteCode}
   and r.rule_type = 'COND'

mapper.update:
update monitor_event
   set detail          = cast(#{detail} as jsonb),
       last_period_end = #{lastPeriodEnd},
       update_time     = #{now}
 where site_code = #{scope.siteCode}
   and event_id = #{eventId}
   and status = 'open'

update monitor_event
   set status      = 'resolved',
       end_hour    = #{endHour},
       update_time = #{now}
 where site_code = #{scope.siteCode}
   and event_id = #{eventId}
   and status = 'open'

update monitor_event
   set notify_status = #{status},
       update_time   = #{now}
 where site_code = #{scope.siteCode}
   and event_id = #{eventId}
